"""Generate docs/parameter_dictionary.md from the config schema (single source of truth: ccsim.config)."""
import _bootstrap
import json

from ccsim.config import DEFAULTS, PARAM_DOC


def flat(d, pre=""):
    for k, v in d.items():
        if isinstance(v, dict):
            yield from flat(v, f"{pre}{k}.")
        else:
            yield f"{pre}{k}", v


def main():
    lines = ["# Parameter dictionary", "",
             "Generated by `scripts/make_docs.py` from `src/ccsim/config.py`. Every constant used by the simulation is in",
             "this schema or in a JSON config (`configs/`, which override these defaults via `extends`).", "",
             "## Documented parameters", "", "| Parameter | Meaning | Default / range / justification |", "|---|---|---|"]
    for k, (desc, rng) in PARAM_DOC.items():
        lines.append(f"| `{k}` | {desc} | {rng} |")
    lines += ["", "## All default values", "", "| Key | Default |", "|---|---|"]
    for k, v in flat(DEFAULTS):
        lines.append(f"| `{k}` | `{json.dumps(v)}` |")
    lines += ["", "## Design-level agent parameters (sampled per design point)", "",
              "| Symbol | Name | Range | Role |", "|---|---|---|---|",
              "| g | admission | [0,1] | P(admit surprising observation) |",
              "| f | structural flexibility | [0,1] | proposal budget = 14 f evaluations per revision |",
              "| c | evaluation / control | [0,1] | complexity penalty 2c and validation margin 0.1(2c-1) |",
              "| pi | error precision | [0.5,2] log-uniform | scales residual evidence, z-scores, predictive variance |",
              "| m | working memory | {2..8} | hypothesis slots and window 12 m |"]
    (_bootstrap.ROOT / "docs" / "parameter_dictionary.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("wrote docs/parameter_dictionary.md")


if __name__ == "__main__":
    main()
